/**
 * When a custom voucher-number toggle is off, prefix and initial-number fields are hidden
 * but still held in the settings form. Sending them on PUT leaves the API applying that
 * prefix to autogenerated numbers. Clear those fields before save when the toggle is off.
 */

export interface CustomNumberPrefixRule {
    enabledKey: string;
    prefixKeys: readonly string[];
}

const INVOICE_SETTINGS_CUSTOM_NUMBER_RULES: readonly CustomNumberPrefixRule[] = [
    {
        enabledKey: 'useCustomInvoiceNumber',
        prefixKeys: ['branchInvoiceNumberPrefix', 'invoiceNumberPrefix', 'initialInvoiceNumber'],
    },
    {
        enabledKey: 'useCustomDebitNoteNumber',
        prefixKeys: ['branchDebitNoteNumberPrefix', 'debitNoteNumberPrefix', 'initialDebitNoteNumber'],
    },
    {
        enabledKey: 'useCustomCreditNoteNumber',
        prefixKeys: ['branchCreditNoteNumberPrefix', 'creditNoteNumberPrefix', 'initialCreditNoteNumber'],
    },
    {
        enabledKey: 'useCustomReceiptNumber',
        prefixKeys: ['branchReceiptNumberPrefix', 'receiptNumberPrefix', 'initialReceiptNumber'],
    },
    {
        enabledKey: 'useCustomPaymentNumber',
        prefixKeys: ['paymentNumberPrefix', 'initialPaymentNumber'],
    },
    {
        enabledKey: 'useCustomContraNumber',
        prefixKeys: ['branchContraNumberPrefix', 'contraNumberPrefix', 'initialContraNumber'],
    },
    {
        enabledKey: 'useCustomPurchaseNumber',
        prefixKeys: ['purchaseNumberPrefix', 'initialPurchaseNumber'],
    },
];

const PURCHASE_BILL_SETTINGS_CUSTOM_NUMBER_RULES: readonly CustomNumberPrefixRule[] = [
    {
        enabledKey: 'useCustomPONumber',
        prefixKeys: ['poNumberPrefix', 'initialPONumber', 'branchPurchaseBillNumberPrefix'],
    },
];

const DELIVERY_CHALLAN_SETTINGS_CUSTOM_NUMBER_RULES: readonly CustomNumberPrefixRule[] = [
    {
        enabledKey: 'useCustomDeliveryChallanNumber',
        prefixKeys: ['deliveryChallanNumberPrefix', 'initialDeliveryChallanNumber', 'branchDeliveryChallanNumberPrefix'],
    },
];

const RECEIPT_NOTE_SETTINGS_CUSTOM_NUMBER_RULES: readonly CustomNumberPrefixRule[] = [
    {
        enabledKey: 'useCustomReceiptNoteNumber',
        prefixKeys: ['receiptNoteNumberPrefix', 'initialReceiptNoteNumber', 'branchReceiptNoteNumberPrefix'],
    },
];

function clearPrefixesForRules(settings: Record<string, unknown>, rules: readonly CustomNumberPrefixRule[]): void {
    for (const rule of rules) {
        if (!settings[rule.enabledKey]) {
            for (const key of rule.prefixKeys) {
                if (key in settings) {
                    settings[key] = null;
                }
            }
        }
    }
}

export function clearInactiveCustomNumberPrefixesOnSettingsSave(formToSave: Record<string, unknown>): void {
    const invoiceSettings = formToSave['invoiceSettings'];
    if (invoiceSettings && typeof invoiceSettings === 'object') {
        clearPrefixesForRules(invoiceSettings as Record<string, unknown>, INVOICE_SETTINGS_CUSTOM_NUMBER_RULES);
    }

    const purchaseBillSettings = formToSave['purchaseBillSettings'];
    if (purchaseBillSettings && typeof purchaseBillSettings === 'object') {
        clearPrefixesForRules(purchaseBillSettings as Record<string, unknown>, PURCHASE_BILL_SETTINGS_CUSTOM_NUMBER_RULES);
    }

    const deliveryChallanSettings = formToSave['deliveryChallanSettings'];
    if (deliveryChallanSettings && typeof deliveryChallanSettings === 'object') {
        clearPrefixesForRules(deliveryChallanSettings as Record<string, unknown>, DELIVERY_CHALLAN_SETTINGS_CUSTOM_NUMBER_RULES);
    }

    const receiptNoteSettings = formToSave['receiptNoteSettings'];
    if (receiptNoteSettings && typeof receiptNoteSettings === 'object') {
        clearPrefixesForRules(receiptNoteSettings as Record<string, unknown>, RECEIPT_NOTE_SETTINGS_CUSTOM_NUMBER_RULES);
    }
}